// Config: everything a business needs to change lives here, so no other node needs editing
// apart from choosing credentials and the Airtable base.
const CONFIG = {
  // Your Airtable base id (the appXXXXXXXXXXXXXX part of the base URL). Tables are found by name.
  airtable_base_id: 'appYOURBASEID',
  business_name: 'Your Business Ltd',
  // The inbox this workflow watches. Mail sent from this address is never treated as a complaint.
  inbox_address: 'user@example.com',
  // Who reviews drafts. Drafts that offer money or goodwill, or are Serious, go to the manager.
  handler_name: 'Your name',
  handler_email: 'you@example.com',
  manager_email: '', // optional; leave empty to send every draft to the handler
  reference_prefix: 'COMP',
  respond_within_working_days: 14,
  approval_wait_days: 3, // after this, the draft is marked "No decision" and the handler is chased
  retention_years: 6,
  // External body the complainant can go to if still unhappy at the end. Leave empty if none.
  redress_scheme: '',
  // Any of these present makes a complaint Serious.
  severity_triggers: 'ombudsman or regulator, solicitor or legal action, fraud or theft, discrimination, data breach, injury or safety risk, loss of money or income',
  // House tone for drafts. The drafter never apologises or admits fault unless your documents say to.
  tone_rules: 'Calm, plain English, firm but courteous. Acknowledge without agreeing or disagreeing. Do not apologise, admit fault or promise an outcome before the facts are established.',
  // The automatic acknowledgement. {name} {reference} {respond_by} {handler_name} {handler_email} {business_name}
  acknowledgement: [
    'Dear {name},',
    '',
    'Thank you for getting in touch. We have received your complaint and logged it under reference {reference}. Please quote this reference on anything further you send us about it.',
    '',
    'We will look into it properly and write to you with a full response by {respond_by}. If we need longer, we will tell you before that date and explain why.',
    '',
    'Your point of contact is {handler_name}, who you can reach at {handler_email}.',
    '',
    'Yours sincerely,',
    '',
    '{handler_name}',
    'For and on behalf of {business_name}',
  ].join('\n'),
};

const unset = ['inbox_address', 'handler_email'].filter((k) => /example\.com/.test(CONFIG[k]));
if (CONFIG.business_name === 'Your Business Ltd') unset.push('business_name');
if (!/^app[A-Za-z0-9]{14}$/.test(CONFIG.airtable_base_id)) unset.push('airtable_base_id');
if (unset.length) throw new Error('Fill in Config first: ' + unset.join(', '));
const input = $input.first().json || {};
return [{ json: { ...CONFIG, message_id: String(input.message_id || input.id || ''), thread_id: String(input.thread_id || input.threadId || '') } }];

// Read Email: turn the Gmail message into plain fields, and decide whether it can be a new
// complaint at all. Automated mail (bounces, newsletters, no-reply senders, auto-replies) and
// our own outgoing mail are screened out here, before any AI call or acknowledgement.
const cfg = $('Config').first().json;
const g = $input.first().json || {};
const dec = (s) => String(s || '')
  .replace(/&#39;|&apos;|&rsquo;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ').replace(/&pound;/g, '£').replace(/&amp;/g, '&');
const htmlToText = (h) => dec(String(h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<\/(p|div|br|tr|li|h[1-6])\s*>/gi, '\n').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();

let body = String(g.text || '').trim();
if (body.length < 40) { const h = htmlToText(g.html || g.textAsHtml || ''); if (h.length > body.length) body = h; }
body = dec(body).trim();
const fromValue = (g.from && Array.isArray(g.from.value) && g.from.value[0]) || {};
const address = String(fromValue.address || '').toLowerCase();
const name = String(fromValue.name || '').trim();
const subject = dec(g.subject || '');
const headers = Object.fromEntries(Object.entries(g.headers || {}).map(([k, v]) => [k.toLowerCase(), String(typeof v === 'object' ? JSON.stringify(v) : v)]));

const prefix = cfg.reference_prefix.replace(/[^A-Za-z0-9]/g, '');
const refMatch = (subject + '\n' + body).match(new RegExp('\\b' + prefix + '-\\d{4}-\\d{6}\\b', 'i'));

let skip = '';
if (!address) skip = 'no sender address';
else if (address === String(cfg.inbox_address).toLowerCase()) skip = 'sent from this inbox';
else if (/^(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounces?)([+.@-]|$)/i.test(address)) skip = 'automated sender';
else if (headers['auto-submitted'] && !/^no$/i.test(headers['auto-submitted'])) skip = 'auto-submitted mail';
else if (headers['list-unsubscribe'] || headers['list-id'] || /bulk|list|junk/i.test(headers['precedence'] || '')) skip = 'mailing list or newsletter';
else if (!body) skip = 'empty message';

return [{
  json: {
    message_id: cfg.message_id || String(g.id || ''),
    thread_id: cfg.thread_id || String(g.threadId || ''),
    from_name: name,
    from_address: address,
    subject,
    body: body.slice(0, 20000),
    received_at: g.date ? new Date(g.date).toISOString() : new Date().toISOString(),
    reference_in_mail: refMatch ? refMatch[0].toUpperCase() : '',
    skip_reason: skip,
  },
}];

// Route Email: SKIP (screened out in Read Email, checked first so an auto-reply on a case
// thread is not logged as a follow-up), FOLLOW_UP on an existing case (same Gmail thread, our
// reference quoted, or an open case from the same address), or NEW. A follow-up never creates a
// second case or a second acknowledgement.
const mail = $('Read Email').first().json;
// A thread or reference match beats a match on the sender's address alone.
const exact = (r) => (mail.thread_id && r['Gmail thread id'] === mail.thread_id) || (mail.reference_in_mail && r.Reference === mail.reference_in_mail);
const found = $input.all().map((i) => i.json || {}).filter((r) => r.id).sort((a, b) => exact(b) - exact(a));
let route = 'NEW';
let reason = 'new message';
if (mail.skip_reason) { route = 'SKIP'; reason = mail.skip_reason; }
else if (found.length) { route = 'FOLLOW_UP'; reason = 'matches case ' + (found[0].Reference || found[0].id); }
return [{ json: { ...mail, route, reason, case_id: found.length ? found[0].id : '', case_reference: found.length ? String(found[0].Reference || '') : '' } }];

// Build Case: the case record, from the classification and the email. The reference, the
// response date and the retention date are worked out here, not by the model.
const cfg = $('Config').first().json;
const mail = $('Route Email').first().json;
const c = $input.first().json.output || {};
const addWorkingDays = (start, days) => {
  const d = new Date(start); let added = 0;
  while (added < days) { d.setUTCDate(d.getUTCDate() + 1); const wd = d.getUTCDay(); if (wd !== 0 && wd !== 6) added++; }
  return d;
};
const dateOnly = (d) => d.toISOString().slice(0, 10);
const received = new Date(mail.received_at);
const respondBy = addWorkingDays(received, Number(cfg.respond_within_working_days) || 14);
const retain = new Date(received); retain.setUTCFullYear(retain.getUTCFullYear() + (Number(cfg.retention_years) || 6));
const now = new Date();
const reference = cfg.reference_prefix.replace(/[^A-Za-z0-9]/g, '') + '-' + now.getUTCFullYear() + '-' + String(now.getTime()).slice(-6);
const severity = ['Low', 'Standard', 'Serious'].includes(c.severity) ? c.severity : 'Standard';
const points = (Array.isArray(c.summary_points) ? c.summary_points : []).map((p) => String(p).trim()).filter(Boolean);
const name = String(c.complainant_name || mail.from_name || '').trim().slice(0, 80);
const respondByText = respondBy.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
const fill = (t) => t.replace(/\{name\}/g, name || 'Sir or Madam').replace(/\{reference\}/g, reference).replace(/\{respond_by\}/g, respondByText)
  .replace(/\{handler_name\}/g, cfg.handler_name).replace(/\{handler_email\}/g, cfg.handler_email).replace(/\{business_name\}/g, cfg.business_name);
return [{
  json: {
    reference,
    severity,
    severity_reason: String(c.severity_reason || ''),
    complainant_name: name,
    summary: points.map((p) => '- ' + p).join('\n'),
    received_at: received.toISOString(),
    respond_by: dateOnly(respondBy),
    respond_by_text: respondByText,
    retention_until: dateOnly(retain),
    acknowledgement: fill(cfg.acknowledgement),
  },
}];

// Assemble Grounding: the only material the drafter may rely on.
//   LIBRARY  your Approved documents (Documents table). The only source of rules and policy.
//   THREAD   this complaint's own email. The only source of facts about this matter.
//   STYLE    your Approved example replies (Examples table). Tone only, never facts.
// Draft documents are simply absent, so the drafter cannot cite them.
const cfg = $('Config').first().json;
const mail = $('Route Email').first().json;
const kase = $('Build Case').first().json;
const rows = (name) => { try { return $(name).all().map((i) => i.json || {}); } catch (e) { return []; } };
const docs = rows('Fetch Documents').filter((d) => d.Status === 'Approved' && String(d.Name || '').trim() && String(d.Content || '').trim());
const library = docs.map((d) => ({ id: String(d.Name).trim(), version: String(d.Version || ''), content: String(d.Content) }));
const examples = rows('Fetch Examples').filter((x) => x.Status === 'Approved' && String(x['Example reply'] || '').trim());
return [{
  json: {
    business_name: cfg.business_name,
    handler_name: cfg.handler_name,
    handler_email: cfg.handler_email,
    tone_rules: cfg.tone_rules,
    redress_scheme: cfg.redress_scheme,
    reference: kase.reference,
    respond_by_text: kase.respond_by_text,
    library_ids: library.map((l) => l.id),
    library_json: library.length ? JSON.stringify(library, null, 2) : '[] (no approved documents: you have nothing to cite)',
    thread_text: 'From: ' + (mail.from_name ? mail.from_name + ' <' + mail.from_address + '>' : mail.from_address) + '\nSubject: ' + mail.subject + '\n\n' + mail.body,
    summary: kase.summary,
    style_text: examples.map((x, i) => 'EXAMPLE ' + (i + 1) + ':\n' + x['Example reply']).join('\n\n----\n\n'),
    feedback: '',
  },
}];

parameters.text:
=You draft complaint replies for {{ $json.business_name }}. A person reviews every draft before anything is sent. An acknowledgement has already gone out, so do not thank them for getting in touch as if this were new, do not re-log the reference and do not promise a new response date. Return JSON only.

GROUNDING RULES (absolute):
1. Rely ONLY on documents in LIBRARY and facts in THREAD. You have no other knowledge. Never state a law, regulation, procedure, deadline or redress route from memory.
2. Every factual, procedural or policy statement carries a marker such as [1]. Each marker has exactly one entry in citations, whose source_id is exactly a LIBRARY id, with a locator (section or heading) and a short verbatim quote. No uncited statements, and no citations to anything outside LIBRARY.
3. Apply the cited rules to this complaint using the THREAD facts, and answer each point they raised.
4. Where a deciding fact is held only in the business's own records and is not in THREAD or LIBRARY, write a placeholder in square brackets, for example "[{{ $json.handler_name }} to confirm: the date the item was returned]", and also list it in unsupported_points. Never guess such facts. A point with no basis in LIBRARY goes in unsupported_points with the reason "no basis on file", and you take no position on it.
5. Tone: {{ $json.tone_rules }}
6. Do not offer money, refunds or goodwill unless a LIBRARY document supports it. If you do, set compensation_proposed to true, describe it in compensation_detail, and say it is offered without admission of liability.
7. Close by inviting them to reply quoting {{ $json.reference }} with any correction or further information. {{ $json.redress_scheme ? 'Say that if they remain dissatisfied once the complaint has been worked through, they may refer it to ' + $json.redress_scheme + '.' : 'Do not mention any external body.' }} Sign off on three lines: {{ $json.handler_name }}, then "Complaints Handler", then "For and on behalf of {{ $json.business_name }}".
8. STYLE shows house tone only. Match its voice and structure where it helps, but never take facts, citations, dates, names, figures or remedies from it. If STYLE is empty, ignore this rule.
{{ $json.feedback ? '\nYOUR PREVIOUS DRAFT WAS REJECTED. Fix these problems: ' + $json.feedback + '\n' : '' }}
REFERENCE: {{ $json.reference }} | FULL RESPONSE DUE BY: {{ $json.respond_by_text }}

LIBRARY (approved sources only):
{{ $json.library_json }}

THREAD (this complaint):
{{ $json.thread_text }}

WHAT THEY RAISED:
{{ $json.summary }}

STYLE (approved past replies, tone only):
{{ $json.style_text || '(none)' }}

parameters.jsCode:
// Check Draft: enforce the citation contract in code, not just in the prompt.
//   - every citation must point at a document that was in LIBRARY
//   - every [n] marker in the draft must have a citation, and every citation a marker
// A failing draft is sent back once with the problems ($runIndex 0). If the second attempt
// still fails, it goes to review with the problems shown in red, so a person decides.
const g = $('Assemble Grounding').first().json;
const d = $input.first().json.output || {};
const ids = g.library_ids || [];
const body = String(d.draft_body || '').trim();
const cites = Array.isArray(d.citations) ? d.citations : [];
const problems = [];
if (!body) problems.push('the draft is empty');
for (const c of cites) if (!ids.includes(c.source_id)) problems.push('citation ' + (c.marker || '?') + ' points at "' + c.source_id + '", which is not an approved document');
const markers = [...new Set((body.match(/\[\d+\]/g) || []))];
const cited = new Set(cites.map((c) => String(c.marker || '').trim()));
for (const m of markers) if (!cited.has(m)) problems.push('marker ' + m + ' in the draft has no citation');
for (const c of cites) if (c.marker && !markers.includes(String(c.marker).trim())) problems.push('citation ' + c.marker + ' is not used in the draft');
const attempt = $runIndex + 1;
const retry = problems.length > 0 && attempt < 2;
return [{
  json: {
    retry,
    attempt,
    problems,
    feedback: problems.join('; '),
    draft_body: body,
    citations: cites,
    unsupported_points: Array.isArray(d.unsupported_points) ? d.unsupported_points : [],
    compensation_proposed: d.compensation_proposed === true,
    compensation_detail: String(d.compensation_detail || ''),
    notes: String(d.notes || ''),
  },
}];

// Prepare Review: the approval email and the send-ready text.
// Drafts that offer money or goodwill, or are Serious, go to the manager when one is set.
// The reviewer gets the reply without [n] markers, ready to edit; the citations, the points the
// drafter could not ground and any problems are shown above it.
const cfg = $('Config').first().json;
const mail = $('Route Email').first().json;
const kase = $('Build Case').first().json;
const d = $input.first().json;
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const br = (s) => esc(s).replace(/\n/g, '<br>');
const toManager = !!cfg.manager_email && (d.compensation_proposed || kase.severity === 'Serious');
const why = d.compensation_proposed ? 'it proposes money or goodwill' : kase.severity === 'Serious' ? 'the complaint is Serious' : '';
const replyText = d.draft_body.replace(/\s?\[\d+\]/g, '').replace(/[ \t]+\n/g, '\n').trim();
const citations = d.citations.map((c) => c.marker + ' ' + c.claim + '\n    ' + c.source_id + (c.locator ? ', ' + c.locator : '') + (c.quote ? ': "' + c.quote + '"' : '')).join('\n');
const unsupported = d.unsupported_points.map((u) => '- ' + u.point + ' (' + (u.reason || 'no basis on file') + ')').join('\n');
const section = (title, text, colour) => text ? '<p><b' + (colour ? ' style="color:' + colour + '"' : '') + '>' + title + '</b><br>' + br(text) + '</p>' : '';
const html = [
  '<p>A draft reply is ready for complaint <b>' + esc(kase.reference) + '</b> from ' + esc(kase.complainant_name || mail.from_address) + '. A full response is due by <b>' + esc(kase.respond_by_text) + '</b>.</p>',
  toManager ? '<p><b>Sent to you as manager because ' + esc(why) + '.</b></p>' : '',
  section('Grounding problems: check every statement before sending', d.problems.join('\n'), '#b00020'),
  section('Severity: ' + kase.severity, kase.severity_reason),
  section('What they raised', kase.summary),
  section('Compensation proposed', d.compensation_proposed ? (d.compensation_detail || 'yes') : ''),
  section('Could not be grounded in your documents', unsupported),
  section('Sources cited in the draft', citations),
  section('Notes from the drafter', d.notes),
  section('Their email', mail.body.slice(0, 4000)),
  '<p>Press the button to read, edit and send the reply. Anything in square brackets marked "to confirm" must be filled in first.</p>',
].filter(Boolean).join('\n');
return [{
  json: {
    approver_email: toManager ? cfg.manager_email : cfg.handler_email,
    approver_role: toManager ? 'Manager' : 'Handler',
    subject: 'Draft reply to approve: ' + kase.reference + (kase.severity === 'Serious' ? ' (Serious)' : ''),
    html,
    reply_text: replyText,
    draft_with_markers: d.draft_body,
    citations_text: citations,
    unsupported_text: unsupported,
    problems_text: d.problems.join('\n'),
    compensation_proposed: d.compensation_proposed,
    wait_days: Number(cfg.approval_wait_days) || 3,
  },
}];

// Read Decision: what the reviewer chose. A reply is only sent when it is non-empty and has no
// "to confirm" placeholder left in it; otherwise the case is put on hold and the handler told.
// No answer within the wait time means NO_ANSWER: nothing is sent and the handler is chased.
const review = $('Prepare Review').first().json;
const data = ($input.first().json || {}).data;
const pick = (o, label) => { if (!o) return ''; const k = Object.keys(o).find((x) => x.toLowerCase() === label); return k ? o[k] : ''; };
const choice = String(pick(data, 'decision') || '');
const reply = String(pick(data, 'reply') || '').replace(/\s?\[\d+\]/g, '').trim();
const note = String(pick(data, 'internal note') || '').trim();
let route;
let reason = '';
if (!data || !choice) { route = 'NO_ANSWER'; reason = 'no decision within ' + review.wait_days + ' days'; }
else if (/^send/i.test(choice)) {
  const placeholder = reply.match(/\[[^\]]*to confirm[^\]]*\]/i);
  if (!reply) { route = 'HOLD'; reason = 'Send was chosen but the reply was empty'; }
  else if (placeholder) { route = 'HOLD'; reason = 'Send was chosen but the reply still contains ' + placeholder[0]; }
  else route = 'SEND';
} else if (/myself/i.test(choice)) route = 'SELF';
else route = 'HOLD';
const status = { SEND: 'Sending', HOLD: 'On hold', SELF: 'Handled personally', NO_ANSWER: 'No decision' }[route];
return [{ json: { route, status, reason, reply_text: reply, note, approver: review.approver_role } }];
